widget.solution:
def contains(parents, tip):
    seen = set()
    todo = [tip]
    while todo:
        c = todo.pop()
        if c not in seen:
            seen.add(c)
            todo.extend(parents[c])
    return seen


def merge_kind(parents, current, other):
    if other in contains(parents, current):
        return "up to date"
    if current in contains(parents, other):
        return "fast-forward"
    return "merge commit"
